files.docroot/v9/eski-sayfalar.css:
/* ek sayfalar: gen_sayfalar.py */
.eski .g5{grid-template-columns:1.5fr repeat(4,1fr)!important}
.eski footer .fp{font-weight:800;font-size:18px;color:#ffffff;margin-top:6px}
@media(max-width:900px){.eski .g5{grid-template-columns:1fr 1fr!important}.eski .g5>div:first-child{grid-column:1/-1}}
.eski .ctg{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.eski .cc{display:block;background:#ffffff;border:1px solid var(--l);border-radius:12px;padding:26px;transition:transform .15s,box-shadow .15s}
.eski .cc:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(58,67,80,.08)}
.eski .cc b{display:block;font-size:17px;margin:12px 0 4px;color:var(--n)}.eski .cc .cbig{display:block;font-size:22px;font-weight:800;color:var(--o);margin-bottom:6px}.eski .cc p{color:#5c6b80}
.eski .fc2{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:start}.eski .fc2 h2{font-size:30px;color:var(--n);margin-bottom:10px}
.eski .tick{list-style:none;padding:0;margin:16px 0 0}.eski .tick li{padding:6px 0 6px 26px;position:relative}.eski .tick li:before{content:"";position:absolute;left:0;top:11px;width:14px;height:8px;border-left:3px solid var(--g);border-bottom:3px solid var(--g);transform:rotate(-45deg)}
.eski .tg{font-size:20px;color:var(--n);margin:28px 0 12px}
.eski .tmg{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.eski .tm{display:block;background:#ffffff;border:1px solid var(--l);border-radius:12px;padding:18px;transition:transform .15s,box-shadow .15s}
.eski .tm:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(58,67,80,.08)}
.eski .tm .sw{display:flex;height:54px;border-radius:8px;overflow:hidden;margin-bottom:12px}.eski .tm .sw i{flex:1}.eski .tm .sw i+i{flex:.35}
.eski .tm b{display:block;color:var(--n)}.eski .tm small{color:#5c6b80}.eski .tm .go{display:block;margin-top:10px;color:var(--o);font-weight:700;font-size:14px}
.eski .blg{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.eski .bl{display:block;background:#ffffff;border:1px solid var(--l);border-radius:12px;padding:24px;transition:transform .15s,box-shadow .15s}
.eski .bl:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(58,67,80,.08)}.eski .bl b{display:block;font-size:18px;color:var(--n);margin-bottom:8px}.eski .bl p{color:#5c6b80}.eski .bl .go{display:block;margin-top:12px;color:var(--o);font-weight:700}
.eski .art{max-width:760px;margin:0 auto;font-size:17px;line-height:1.7}.eski .art h2{font-size:24px;color:var(--n);margin:28px 0 8px}.eski .art p,.eski .art ul{margin:0 0 14px}.eski .art ul{padding-left:22px}.eski .art li{margin-bottom:6px}.eski .art a{color:var(--b);text-decoration:underline}
.eski .calc{display:grid;grid-template-columns:1.2fr 1fr;gap:28px;align-items:start}.eski .calc .note2{grid-column:1/-1}
.eski .cin{display:grid;grid-template-columns:1fr 1fr;gap:14px}.eski .cin label{display:block;font-size:13px;font-weight:600;margin-bottom:4px;color:var(--n)}
.eski .cin input{width:100%;padding:12px;border:1px solid #d7dce2;border-radius:8px;font:inherit}.eski .cin input:focus{outline:2px solid var(--b);border-color:var(--b)}
.eski .cout{background:var(--n);color:#ffffff;border-radius:12px;padding:22px;display:grid;grid-template-columns:1fr auto;gap:10px 16px;margin:0}.eski .cout dt{opacity:.8}.eski .cout dd{margin:0;font-weight:800;text-align:right}
@media(max-width:900px){.eski .ctg,.eski .blg{grid-template-columns:1fr}.eski .tmg{grid-template-columns:1fr 1fr}.eski .fc2,.eski .calc{grid-template-columns:1fr}.eski .cin{grid-template-columns:1fr}}
@media(max-width:480px){.eski .tmg{grid-template-columns:1fr}}
.eski .ctg.c4{grid-template-columns:repeat(4,1fr)}.eski .cc .go{display:block;margin-top:10px;color:var(--o);font-weight:700;font-size:14px}
@media(max-width:900px){.eski .ctg.c4{grid-template-columns:1fr 1fr}}@media(max-width:480px){.eski .ctg.c4{grid-template-columns:1fr}}
.eski #daha{padding:56px 0;background:#f5f6f8}.eski #daha .sh h2{font-size:30px;color:var(--n);margin-bottom:22px}
.eski #daha .ib{display:none}.eski #daha .cc{border-top:4px solid var(--o);padding:24px}.eski #daha .cc:nth-child(2){border-top-color:var(--b)}.eski #daha .cc:nth-child(3){border-top-color:var(--g)}.eski #daha .cc:nth-child(4){border-top-color:var(--p)}
.eski #daha .cc b{margin-top:0;font-size:19px}

files.docroot/v9/eski-sektor.css:
/* sektor-*.html — yeni.css üzerine sektör sayfası bileşenleri */
.eski main{--ac:#6a7b92;--ad:#576477}
.eski main.a-kombi{--ac:#6a7b92;--ad:#576477}
.eski main.a-klima{--ac:#67788f;--ad:#525f71}
.eski main.a-beyaz-esya{--ac:#97a3b3;--ad:#74849b}
.eski main.a-elektronik{--ac:#6b7c94;--ad:#6b7c94}
.eski main.a-bilgisayar{--ac:#586679;--ad:#424c5a}
.eski main.a-tesisat{--ac:#4b5768;--ad:#404a59}
.eski main.a-elektrik{--ac:#6b7c94;--ad:#4f5c6e}
.eski main.a-guvenlik{--ac:#73839a;--ad:#5c6b80}

/* ---- hero (.pgh) ---- */
.eski .pgh .w{padding-top:46px;padding-bottom:52px;gap:44px}
.eski .pgh h1{max-width:620px}
.eski .pgh .ticks li{display:flex;gap:10px;font-weight:500;color:#2b3340}
.eski .pgh .ticks li:before{flex:none}
.eski .ctas{display:flex;flex-wrap:wrap;gap:14px;margin-top:26px}
.eski .ctas .pill{padding:13px 26px;font-size:15px}
.eski .pill.gh{background:#ffffff1f;box-shadow:inset 0 0 0 2px #ffffff;color:#ffffff}
.eski .pill.gh:hover{background:#ffffff38}
.eski .skv{position:relative;padding:68px 22px 22px;border-radius:26px;background:linear-gradient(160deg,#ffffff2e,#ffffff12);box-shadow:inset 0 0 0 1px #ffffff40,0 24px 50px #353e4a66}
.eski .skic{position:absolute;right:26px;top:-22px;width:88px;height:88px;padding:11px;border-radius:24px;background:#ffffff;box-shadow:0 0 0 5px var(--ac),0 14px 30px #353e4a77;z-index:2}
.eski .fis{background:#ffffff;color:#3a4350;border-radius:16px;overflow:hidden;box-shadow:0 12px 30px #353e4a55}
.eski .fis .top{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;background:var(--ad);color:#ffffff;font-weight:800;font-size:13px;padding:13px 18px}
.eski .fis dl{display:grid;grid-template-columns:76px minmax(0,1fr);gap:7px 12px;padding:16px 18px 6px;font-size:14px}
.eski .fis dt{color:#576477;font-weight:600}.eski .fis dd{font-weight:700;margin:0;overflow-wrap:anywhere}
.eski .fis .ln{display:grid;grid-template-columns:48px minmax(0,1fr);gap:12px;align-items:center;padding:7px 18px;font-size:13.5px;position:relative}
.eski .fis dl+.ln{border-top:1px dashed #c6ccd5;margin-top:8px;padding-top:14px}
.eski .fis .ln time{font-weight:800;color:var(--ad)}
.eski .fis .ln span{position:relative;padding-left:16px}
.eski .fis .ln span:before{content:"";position:absolute;left:0;top:.45em;width:8px;height:8px;border-radius:50%;background:var(--ac)}
.eski .fis .tot{margin-top:8px;padding:14px 18px;background:#f2f3f5;font-weight:800;font-size:17px;text-align:right}

/* ---- ortak bant düzeni: solda başlık, sağda içerik ---- */
.eski .bnd{padding:40px 0}
.eski .bnd>.w{display:grid;grid-template-columns:minmax(0,270px) minmax(0,1fr);gap:34px;align-items:start}
.eski .sh.one h2{font-size:28px;line-height:1.15;letter-spacing:-.015em;font-weight:800;color:var(--n)}
.eski .sh.one h2:before{content:"";display:block;width:46px;height:5px;border-radius:3px;background:linear-gradient(90deg,var(--ac),#6a7b92);margin-bottom:14px}

/* sorunlar */
.eski .pb{background:linear-gradient(180deg,#ffffff,#f9f9fa)}
.eski .fgrid{display:grid;gap:14px;counter-reset:f}
.eski .fgrid>div{counter-increment:f;display:grid;grid-template-columns:48px minmax(0,1fr) minmax(0,.95fr);column-gap:18px;row-gap:4px;align-items:start;background:#ffffff;border:1px solid #e5e8ed;border-radius:18px;padding:18px 20px;box-shadow:0 10px 26px #59677b2e}
.eski .fgrid>div:before{content:counter(f);grid-row:1/3;width:44px;height:44px;border-radius:14px;display:grid;place-items:center;font-size:20px;font-weight:800;color:#ffffff;background:linear-gradient(135deg,#5f6e84,#6a7b92);box-shadow:0 6px 14px #6a7b9255}
.eski .fgrid>div:nth-child(2):before{background:linear-gradient(135deg,#6b7c94,#8d9aac);box-shadow:0 6px 14px #6b7c9455}
.eski .fgrid>div:nth-child(3):before{background:linear-gradient(135deg,#8392a6,#a4aebd);box-shadow:0 6px 14px #97a3b355}
.eski .fgrid h3{grid-column:2;font-size:17px;line-height:1.25;color:var(--n);align-self:end}
.eski .fgrid p{font-size:14px;color:#424c5b}
.eski .fgrid p:first-of-type{grid-column:2}
.eski .fgrid p:last-of-type{grid-column:3;grid-row:1/3;align-self:stretch;background:#eceef1;border-left:4px solid #586679;border-radius:4px 12px 12px 4px;padding:11px 14px;color:#38414e}
.eski .fgrid p b{color:#3c4552}

/* hazır gelenler */
.eski .tint{background:linear-gradient(180deg,#e8ebef,#f2f3f5)}
.eski .set{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:18px;align-items:stretch}
.eski .set>div{border-radius:20px;padding:22px 24px}
.eski .set>div:first-child{background:#ffffff;box-shadow:0 12px 30px #59677b3a}
.eski .set>div:last-child{color:#2b3340;background:#f5f6f8;box-shadow:0 14px 34px #3f495755}
.eski .set h3{font-size:16px;margin-bottom:12px;color:var(--n)}
.eski .set>div:last-child h3{color:#2b3340}
.eski .set h3[style]{margin-top:24px!important}
.eski .chp{display:flex;flex-wrap:wrap;gap:8px}
.eski .chp span{background:#eff1f4;color:#465161;font-weight:700;font-size:13px;border-radius:999px;padding:6px 13px}
.eski .chp+h3+.chp span{background:#eaedf0;color:#3f4957}
.eski .set .ticks{list-style:none;padding:0;display:grid;gap:0}
.eski .set .ticks li{display:flex;gap:10px;padding:9px 0;border-bottom:1px solid #ffffff24;font-weight:500}
.eski .set .ticks li:last-child{border:0}
.eski .set .ticks li:before{content:"✓";color:#8e9bad;font-weight:800}
.eski .note2{margin-top:12px;font-size:13px;color:#e0e4e9}

/* akış */
.eski .sq{background:#f5f6f8;color:#2b3340}
.eski .sq .sh.one h2{color:#2b3340}
.eski .seq{list-style:none;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;counter-reset:q}
.eski .seq li{counter-increment:q;position:relative}
.eski .seq i{display:grid;place-items:center;width:46px;height:46px;border-radius:50%;margin-bottom:12px;color:#ffffff;font-style:normal;font-weight:800;font-size:19px;box-shadow:0 0 0 6px #ffffff1f,0 8px 18px #00000066;position:relative;z-index:1;background:#7d8ca1}
.eski .seq i:before{content:counter(q)}
.eski .seq li:nth-child(2) i{background:#97a3b3}.eski .seq li:nth-child(3) i{background:#5f6e84}.eski .seq li:nth-child(4) i{background:#4c5868}
.eski .seq li:not(:last-child):after{content:"";position:absolute;top:22px;left:62px;right:-12px;height:2px;background:#98a4b5}
.eski .seq time{display:block;font-weight:800;font-size:18px;color:#a0abbb}
.eski .seq b{display:block;font-size:16px;margin:2px 0 4px}
.eski .seq p{font-size:14px;color:#f5f6f8}

/* paket bandı */
.eski .ctab{padding:36px 0}
.eski .cta2{display:flex;align-items:center;justify-content:space-between;gap:28px;border-radius:22px;padding:28px 36px;color:#2b3340;background:#f5f6f8;box-shadow:0 16px 40px #59677b4d}
.eski .cta2>div{min-width:0}.eski .cta2 h2{font-size:28px;line-height:1.15}.eski .cta2 p{margin-top:8px;color:#2b3340;max-width:620px}
.eski .cta2 .pill{flex:none;padding:14px 28px;font-size:15px}

/* sss */
.eski #sss{padding:40px 0}
.eski .sss{display:grid;grid-template-columns:minmax(0,270px) minmax(0,1fr);gap:34px;align-items:start}
.eski .sss h2{font-size:28px;line-height:1.15;letter-spacing:-.015em;color:var(--n)}
.eski .sss h2:before{content:"";display:block;width:46px;height:5px;border-radius:3px;background:linear-gradient(90deg,var(--ac),#6a7b92);margin-bottom:14px}
.eski .sss>div{display:grid;gap:10px}
.eski .sss details{border-radius:12px;border-left:4px solid var(--ac)}
.eski .sss summary{padding:15px 18px;font-size:15px;color:var(--n)}
.eski .sss details p{padding:0 18px 16px;font-size:14px}

/* diğer sektörler */
.eski .oth{padding:40px 0 30px}
.eski .chp.rel{gap:10px}
.eski .chp.rel a{display:inline-flex;align-items:center;gap:9px;background:#ffffff;color:var(--n);font-weight:700;font-size:14px;border-radius:999px;padding:10px 18px;box-shadow:0 4px 14px #59677b2e;border:1px solid #e5e8ed}
.eski .chp.rel a:hover{box-shadow:0 8px 20px #59677b4a}
.eski .chp.rel a:before{content:"";width:10px;height:10px;border-radius:50%;background:#6b7c94}
.eski .chp.rel a:nth-child(1):before{background:#6a7b92}.eski .chp.rel a:nth-child(2):before{background:#67788f}.eski .chp.rel a:nth-child(3):before{background:#97a3b3}
.eski .chp.rel a:nth-child(4):before{background:#6b7c94}.eski .chp.rel a:nth-child(5):before{background:#586679}.eski .chp.rel a:nth-child(6):before{background:#4b5768}
.eski .chp.rel a:nth-child(7):before{background:#6b7c94}.eski .chp.rel a:nth-child(8):before{background:#73839a}
.eski .chp.rel a:last-child{background:var(--n);color:#ffffff;border-color:var(--n)}.eski .chp.rel a:last-child:before{display:none}

.eski footer img{height:34px;width:auto}
/* form */
.eski .dkk{padding:48px 0}
.eski .dkk .frm [role=status][style*="rgb(15, 157, 88)"]{color:#3e4856!important}
.eski .dkk .frm .bt:hover{filter:brightness(1.06)}

@media(max-width:1060px){
 .eski .pgh .w{gap:38px}
 .eski .skv{margin-top:12px}
 .eski .bnd>.w,.eski .sss{grid-template-columns:1fr;gap:20px}
 .eski .bnd{padding:34px 0}
 .eski .seq{grid-template-columns:repeat(2,minmax(0,1fr));row-gap:28px}
 .eski .seq li:nth-child(2):after{display:none}
 .eski .set{grid-template-columns:1fr}
 .eski .cta2{flex-direction:column;align-items:flex-start}
}
@media(max-width:700px){
 .eski .fgrid>div{grid-template-columns:44px minmax(0,1fr);padding:16px}
 .eski .fgrid>div:before{grid-row:1/2}
 .eski .fgrid p:first-of-type{grid-column:1/-1}
 .eski .fgrid p:last-of-type{grid-column:1/-1;grid-row:auto}
 .eski .fgrid h3{align-self:center}
 .eski .seq{grid-template-columns:1fr;row-gap:0}
 .eski .seq li{display:grid;grid-template-columns:46px minmax(0,1fr);column-gap:16px;padding-bottom:22px}
 .eski .seq i{grid-row:1/3;margin:0}
 .eski .seq li:not(:last-child):after,.eski .seq li:nth-child(2):after{display:block;top:46px;bottom:0;left:22px;right:auto;width:2px;height:auto}
 .eski .seq time{align-self:end}
 .eski .set>div{padding:18px}
 .eski .ctab{padding:26px 0}.eski .cta2{padding:24px 20px}.eski .cta2 h2{font-size:24px}
 .eski .cta2 .pill{align-self:stretch}
}
