.eski .skip{position:absolute;left:-9999px;top:0;background:#ffffff;color:#3a4350;padding:10px 16px;z-index:100;border-radius:0 0 8px 0}.eski .skip:focus{left:0}
.eski :focus-visible{outline:3px solid #8e9bad;outline-offset:2px}
.eski .crumb{font-size:13px;color:#d6dbe1;margin-bottom:14px}.eski .crumb a{color:#ffffff;text-decoration:underline;text-underline-offset:3px}
.eski .pgh{background:#f5f6f8;color:#2b3340}
.eski .pgh .w{padding-top:44px;padding-bottom:48px;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:30px;align-items:center}
.eski .pgh h1{font-size:42px;line-height:1.1;font-weight:800;letter-spacing:-.02em}
.eski .pgh p{color:#2b3340;font-size:17px;margin:14px 0 18px;max-width:560px}
.eski .pgh .ticks{list-style:none;padding:0;display:grid;gap:7px;margin:0 0 6px}.eski .pgh .ticks li:before{content:"✓";color:#2b3340;font-weight:800;margin-right:10px}
.eski .mnu{display:none}
@media(max-width:1060px){
 .eski{padding-bottom:calc(84px + env(safe-area-inset-bottom))!important}
 .eski .vb{position:fixed;z-index:90;left:0;right:0;bottom:0;display:grid;grid-template-columns:1.2fr 1fr;gap:10px;padding:11px 12px calc(11px + env(safe-area-inset-bottom));background:#ffffff;border-top:1px solid #e5e8ed;box-shadow:0 -8px 24px #59677b2e}
 .eski .vb a{height:54px;border-radius:30px;display:flex;align-items:center;justify-content:center;gap:8px;color:#ffffff;font-weight:800;font-size:15px;white-space:nowrap}
 .eski .vb .p1{background:linear-gradient(100deg,#3f4957,#6b7c94);box-shadow:0 6px 16px #6b7c9455}
 .eski .vb .p2{background:linear-gradient(100deg,#4c596a,#6d7e95);box-shadow:0 6px 16px #4c596a55}
 .eski .vb .ci{width:30px;height:30px;border-radius:50%;background:#ffffff2e;display:grid;place-items:center;flex:none}.eski .vb .ci svg{width:16px;height:16px}
 .eski .mnu.on{display:flex;position:fixed;z-index:80;left:0;right:0;bottom:0;flex-direction:column;background:#f5f6f8;padding-bottom:calc(84px + env(safe-area-inset-bottom))}
 .eski .mn-l{flex:1;overflow:auto;padding:8px 22px}
 .eski .mn-l a{display:flex;align-items:center;gap:14px;padding:15px 0;border-bottom:1px solid #ffffff2a;color:#ffffff}
 .eski .mn-l a b{display:none}.eski .mn-l a span{flex:1;font-weight:800;font-size:21px;line-height:1.15;display:flex;flex-direction:column;gap:2px}
 .eski .mn-l a small{font-weight:500;font-size:13px;color:#cdd2da}.eski .mn-l a svg{color:#8e9bad}
 .eski .mn-f{display:grid;grid-template-columns:1fr 1.3fr;gap:10px;padding:14px 22px}
 .eski .mn-f a{height:52px;border-radius:30px;display:grid;place-items:center;font-weight:800;font-size:16px}
 .eski .mn-g{border:2px solid #ffffff;color:#ffffff}.eski .mn-c{background:linear-gradient(135deg,#6a7b92,#8e9bad);color:#ffffff;box-shadow:0 6px 16px #6a7b9266}
 .eski .pgh .w{grid-template-columns:1fr;padding-top:34px;padding-bottom:36px}.eski .pgh h1{font-size:32px}
}
@media(min-width:1061px){.eski .vb{display:none}}
/* form bölümü */
.eski .dkk{background:#f5f6f8;color:#2b3340;padding:44px 0}
.eski .dkk .fc{display:grid;grid-template-columns:1fr 1fr;gap:34px;align-items:center}.eski .dkk .fc>*{min-width:0}
.eski .dkk h2{font-size:32px;line-height:1.15}.eski .dkk p{color:#2b3340;margin:8px 0 16px}
.eski .dkk .big{display:inline-block;font-size:30px;font-weight:800;color:#2b3340}
.eski .dkk .frm,.eski .frm.st{display:grid;grid-template-columns:1fr 1fr;gap:12px;background:#ffffff;border-radius:16px;padding:20px;color:#3a4350;box-shadow:0 18px 40px #00000066}
.eski .dkk .frm label{position:static;font-size:13px;font-weight:700;color:#424c5b;display:block;margin-bottom:4px;left:auto}
.eski .dkk .frm input,.eski .dkk .frm select{width:100%;height:46px;border:1.5px solid #d9dee4;border-radius:10px;padding:0 12px;font-size:15px;background:#ffffff;color:#3a4350;margin:0}
.eski .dkk .frm .bt{grid-column:1/-1;justify-self:stretch;text-align:center;display:inline-flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#6a7b92,#8694a7);color:#2b3340;font-weight:800;border-radius:999px;padding:14px;cursor:pointer;box-shadow:0 6px 16px #6a7b9255}
.eski .dkk .frm small{grid-column:1/-1;color:#5f6e84;font-size:12px}
@media(max-width:1060px){.eski .dkk .fc{grid-template-columns:1fr}.eski .dkk .frm{grid-template-columns:1fr}.eski .dkk h2{font-size:26px}}
/* altbilgi */
.eski footer{background:#38414e;color:#cdd2da;padding:44px 0 26px;font-size:14px}
.eski footer .w{display:block}.eski footer .g{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:28px}
.eski footer .g>*{min-width:0}.eski footer p{margin-top:12px;max-width:300px;line-height:1.5}
.eski footer h5{color:#ffffff;font-size:14px;margin-bottom:10px}.eski footer .g a{display:block;margin:0 0 7px;color:#cdd2da}.eski footer .g a:hover{color:#8e9bad}
.eski footer .cp{display:flex;justify-content:space-between;gap:12px;border-top:1px solid #ffffff22;margin-top:26px;padding-top:16px;font-size:13px}
@media(max-width:700px){.eski footer .g{grid-template-columns:1fr 1fr}.eski footer .g>div:first-child{grid-column:1/-1}}
@media(max-width:1060px){.eski .mn-f{background:transparent;border-top:1px solid #ffffff2a}.eski .mn-l{border:0}}
/* erişilebilir turuncu: beyaz yazı >= 4.5:1 */
.eski .pill,.eski .pc.pop .pill,.eski .dkk .frm .bt,.eski .mn-c{background:linear-gradient(135deg,#515d6f,#546275);color:#2b3340}
.eski .pill.ol{background:#ffffff;color:#4b5767}
.eski .pc.pop h3{background:linear-gradient(135deg,#515d6f,#546275)}
.eski .pc .tag{color:#4b5767}
.eski .pc .pill{background:#ffffff;color:#3a4350}.eski .pc.pop .pill{background:linear-gradient(135deg,#515d6f,#546275);color:#ffffff}
@media(max-width:1060px){.eski .vb .p2{background:linear-gradient(100deg,#404a58,#444f5e)}}
.eski footer .g img{height:34px;width:auto}
/* geliştirme: cila */
.eski{scroll-behavior:smooth;scroll-padding-top:84px}
.eski header{transition:box-shadow .2s}.eski header.sc{box-shadow:0 6px 22px #3a435020}
.eski header nav.m a{position:relative;padding:6px 0}
.eski header nav.m a:after{content:"";position:absolute;left:0;right:0;bottom:-2px;height:2px;background:var(--o);transform:scaleX(0);transition:transform .2s;transform-origin:left}
.eski header nav.m a:hover:after,.eski header nav.m a[aria-current]:after{transform:scaleX(1)}
.eski .pill{transition:transform .15s,box-shadow .15s,filter .15s}.eski .pill:hover{transform:translateY(-1px);filter:brightness(1.05)}.eski .pill:active{transform:translateY(1px)}
.eski .sg a,.eski .pc,.eski details,.eski .kz{transition:transform .18s,box-shadow .18s}
.eski .sg a:hover,.eski .pc:hover{transform:translateY(-3px)}
.eski .pc.pop:hover{transform:translateY(-7px)}
.eski input:focus,.eski select:focus{outline:3px solid #8e9bad;outline-offset:1px}
.eski .frm [aria-invalid=true]{border-color:#566376!important}
.eski details[open] summary{color:var(--o2)}
@media(prefers-reduced-motion:reduce){.eski *{transition:none!important;scroll-behavior:auto!important}}
.eski{--o2:#4b5767}
.eski .tsx div:nth-child(1){background:#6b7c94!important}.eski .tsx div:nth-child(2){background:#546275!important}.eski .tsx div:nth-child(3){background:#424c5a!important}.eski .tsx div:nth-child(4){background:#8291a5!important}

.eski .yz{padding:48px 0 72px}.eski .yz .w{max-width:820px}.eski .yz h2{font-size:22px;color:var(--n);margin:30px 0 8px}.eski .yz p{font-size:16px;line-height:1.7;color:#3e4856}.eski .yz a{color:var(--o2);text-decoration:underline}.eski .yz .nt{background:#f2f3f5;border-left:4px solid var(--o);padding:12px 16px;border-radius:6px;font-size:14px}
.eski .crumb,.eski .crumb a{color:#5b6573}
.eski a.pill.gh{background:#fff;box-shadow:inset 0 0 0 2px #2b3340;color:#2b3340}
.eski a.pill.gh:hover{background:#eef0f3}
.eski .pgh .jump a,.eski .pkh .jump a{color:#2b3340}
.eski a.pill,.eski button.pill,.eski .dkk .frm .bt,.eski .mn-c{color:#fff}
.eski a.pill.gh,.eski a.pill.ol{background:#fff;color:#2b3340;box-shadow:inset 0 0 0 2px #2b3340}
.eski .pc a.pill{color:#3a4350}.eski .pc.pop a.pill{color:#fff}
.eski .sh{position:static;height:auto}
.eski a.btn.bos{background:#fff;color:#2b3340;box-shadow:inset 0 0 0 2px #2b3340;border:0}
.eski a.btn.bos:hover{background:#eef0f3}
.eski .cout{background:#f5f6f8;color:#2b3340;box-shadow:inset 0 0 0 1.5px #d9dee4}
.eski a.bt.l,.eski .bt.l{background:#fff;color:#2b3340;box-shadow:inset 0 0 0 2px #2b3340;border:0}
.eski a.bt.l:hover{background:#eef0f3}
